mapper.select:
SELECT

FROM t_memory
WHERE user_id = #{userId}
  AND deleted = 0
  AND created_at >= #{startTime}
  AND created_at <= #{endTime}
ORDER BY created_at DESC

mapper.update:
UPDATE t_memory
title = #{title}, content = #{content}, summary = #{summary}, metadata = #{metadata}, vector_id = #{vectorId}, is_important = #{isImportant}, updated_at = #{updatedAt},
WHERE id = #{id}

UPDATE t_memory
SET deleted = 1, updated_at = NOW()
WHERE id = #{id}
